/**
 * Zoho CRM Node - Version 1
 * Discriminator: resource=vendor, operation=update
 */


interface Credentials {
  zohoOAuth2Api: CredentialReference;
}

/** Update an account */
export type ZohoCrmV1VendorUpdateParams = {
  resource: 'vendor';
  operation: 'update';
/**
 * ID of the vendor to update
 */
    vendorId: string | Expression<string>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Address
     * @default {}
     */
    Address?: {
        /** Address Fields
     */
    address_fields?: {
      /** Street
       */
      Street?: string | Expression<string>;
      /** City
       */
      City?: string | Expression<string>;
      /** State
       */
      State?: string | Expression<string>;
      /** Country
       */
      Country?: string | Expression<string>;
      /** Zip Code
       */
      Zip_Code?: string | Expression<string>;
    };
  };
    /** Category
     */
    Category?: string | Expression<string>;
    /** Currency
     */
    Currency?: string | Expression<string>;
    /** Filter by custom fields
     * @default {}
     */
    customFields?: {
        /** Custom Field
     */
    customFields?: Array<{
      /** Custom field to set a value to
       * @loadOptionsMethod getCustomVendorFields
       */
      fieldId?: string | Expression<string>;
      /** Value to set on custom field
       */
      value?: string | Expression<string>;
    }>;
  };
    /** Description
     */
    Description?: string | Expression<string>;
    /** Email
     */
    Email?: string | Expression<string>;
    /** Phone
     */
    Phone?: string | Expression<string>;
    /** Vendor Name
     */
    Vendor_Name?: string | Expression<string>;
    /** Website
     */
    Website?: string | Expression<string>;
  };
};

export type ZohoCrmV1VendorUpdateNode = {
  type: 'n8n-nodes-base.zohoCrm';
  version: 1;
  config: NodeConfig<ZohoCrmV1VendorUpdateParams> & { credentials?: Credentials };
};